        existingComments.put("path1", Arrays.asList("line1"));
        CommentsConfiguration config = new CommentsConfiguration(existingComments);
        assertEquals(existingComments, config.comments);
    }

    @Test
    public void setComment_setsNewLinesForPath() {
        CommentsConfiguration config = new CommentsConfiguration();
        config.setComment("path1", "\n", "new-line");
        assertTrue(config.comments.get("path1").contains("\n"));
        assertFalse(config.comments.get("path1").isEmpty());
    }

    @Test
    public void setComment_setsMultipleLinesForPath() {
